@page "/chat"
@layout ChatLayout
@using sv_c5b2b52773ce4523a9f14bff1c880c59.Models
@inject IChatService ChatService
@rendermode InteractiveServer

<div class="chat-container">
    @* ===== LEFT SIDEBAR ===== *@
    <aside class="channel-sidebar">
        <div class="sidebar-header">
            <h2>Channels</h2>
        </div>
        <ul class="channel-list">
            @if (_channels is not null)
            {
                @foreach (var channel in _channels)
                {
                    <li class="channel-item @(channel.Id == _activeChannelId ? "active" : "")"
                        @onclick="() => SelectChannelAsync(channel)">
                        <div class="channel-name"># @channel.Name</div>
                        <div class="channel-desc">@TruncateDescription(channel.Description)</div>
                        @if (channel.UnreadCount > 0)
                        {
                            <span class="unread-badge">@channel.UnreadCount</span>
                        }
                    </li>
                }
            }
        </ul>
    </aside>

    @* ===== MAIN MESSAGE AREA ===== *@
    <section class="message-area @(_threadOpen ? "thread-open" : "")">
        @if (_activeChannel is not null)
        {
            <div class="message-header">
                <h3># @_activeChannel.Name</h3>
                <span class="channel-description">@_activeChannel.Description</span>
            </div>

            <div class="message-list" @ref="_messageListRef" @onscroll="HandleScrollAsync">
                @if (_loadingOlder)
                {
                    <div class="loading-indicator">Loading older messages…</div>
                }
                @if (_messages is not null)
                {
                    @foreach (var msg in _messages)
                    {
                        <div class="message-row" @onmouseenter="() => _hoveredMessageId = msg.Id"
                             @onmouseleave="() => _hoveredMessageId = null">
                            <div class="message-content-wrapper">
                                <div class="message-meta">
                                    <span class="msg-author">@msg.Author</span>
                                    <span class="msg-time">@FormatRelativeTime(msg.SentAt)</span>
                                </div>
                                <div class="msg-body">@msg.Content</div>

                                @if (msg.Reactions.Count > 0)
                                {
                                    <div class="reaction-row">
                                        @foreach (var reaction in msg.Reactions)
                                        {
                                            <button class="reaction-badge" title="@string.Join(", ", reaction.Users)"
                                                    @onclick="() => ReactAsync(msg.Id, reaction.Emoji)">
                                                @reaction.Emoji @reaction.Users.Count
                                            </button>
                                        }
                                    </div>
                                }

                                @{ var summary = GetThreadSummary(msg.Id); }
                                @if (summary is not null)
                                {
                                    <button class="thread-link" @onclick="() => OpenThreadAsync(msg)">
                                        @summary.ReplyCount @(summary.ReplyCount == 1 ? "reply" : "replies")
                                        &middot; Last reply @FormatRelativeTime(summary.LastReplyAt)
                                    </button>
                                }
                            </div>

                            @if (_hoveredMessageId == msg.Id)
                            {
                                <div class="message-actions">
                                    <button class="action-btn" title="Reply in thread"
                                            @onclick="() => OpenThreadAsync(msg)">
                                        💬
                                    </button>
                                    <button class="action-btn" title="Add reaction"
                                            @onclick="() => ToggleEmojiPicker(msg.Id)">
                                        😀
                                    </button>
                                </div>
                            }

                            @if (_emojiPickerMessageId == msg.Id)
                            {
                                <div class="emoji-picker">
                                    @foreach (var emoji in _commonEmojis)
                                    {
                                        <button class="emoji-option" @onclick="() => PickEmojiAsync(msg.Id, emoji)">
                                            @emoji
                                        </button>
                                    }
                                </div>
                            }
                        </div>
                    }
                }
            </div>

            <div class="message-input-area">
                <textarea class="message-input" rows="2" placeholder="Message #@_activeChannel.Name"
                          @bind="_newMessageText" @bind:event="oninput"
                          @onkeydown="HandleMainKeyDown"></textarea>
                <button class="send-btn" @onclick="SendMessageAsync" disabled="@string.IsNullOrWhiteSpace(_newMessageText)">
                    Send
                </button>
            </div>
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </section>

    @* ===== RIGHT THREAD PANEL ===== *@
    @if (_threadOpen && _threadRootMessage is not null)
    {
        <aside class="thread-panel">
            <div class="thread-header">
                <h3>Thread</h3>
                <button class="close-thread-btn" @onclick="CloseThread" title="Close thread">✕</button>
            </div>

            <div class="thread-root-quote">
                <div class="message-meta">
                    <span class="msg-author">@_threadRootMessage.Author</span>
                    <span class="msg-time">@FormatRelativeTime(_threadRootMessage.SentAt)</span>
                </div>
                <div class="msg-body">@_threadRootMessage.Content</div>
            </div>

            <div class="thread-divider">
                @if (_threadReplies is not null)
                {
                    <span>@_threadReplies.Count @(_threadReplies.Count == 1 ? "reply" : "replies")</span>
                }
            </div>

            <div class="thread-messages">
                @if (_threadReplies is not null)
                {
                    @foreach (var reply in _threadReplies)
                    {
                        <div class="message-row thread-reply">
                            <div class="message-content-wrapper">
                                <div class="message-meta">
                                    <span class="msg-author">@reply.Author</span>
                                    <span class="msg-time">@FormatRelativeTime(reply.SentAt)</span>
                                </div>
                                <div class="msg-body">@reply.Content</div>

                                @if (reply.Reactions.Count > 0)
                                {
                                    <div class="reaction-row">
                                        @foreach (var reaction in reply.Reactions)
                                        {
                                            <button class="reaction-badge"
                                                    @onclick="() => ReactAsync(reply.Id, reaction.Emoji)">
                                                @reaction.Emoji @reaction.Users.Count
                                            </button>
                                        }
                                    </div>
                                }
                            </div>
                        </div>
                    }
                }
            </div>

            <div class="message-input-area">
                <textarea class="message-input" rows="2" placeholder="Reply…"
                          @bind="_threadReplyText" @bind:event="oninput"
                          @onkeydown="HandleThreadKeyDown"></textarea>
                <button class="send-btn" @onclick="SendThreadReplyAsync"
                        disabled="@string.IsNullOrWhiteSpace(_threadReplyText)">
                    Reply
                </button>
            </div>
        </aside>
    }
</div>

@code {
    private const int PageSize = 30;

    private List<Channel>? _channels;
    private int? _activeChannelId;
    private Channel? _activeChannel;

    private List<Message>? _messages;
    private int _messageSkip;
    private bool _loadingOlder;
    private bool _allOlderLoaded;

    private int? _hoveredMessageId;
    private int? _emojiPickerMessageId;

    private string _newMessageText = string.Empty;
    private string _threadReplyText = string.Empty;

    private bool _threadOpen;
    private Message? _threadRootMessage;
    private List<Message>? _threadReplies;

    // Thread summaries keyed by root message id
    private Dictionary<int, ThreadSummary> _threadSummaries = new();

    private ElementReference _messageListRef;

    private readonly string[] _commonEmojis = ["👍", "❤️", "😂", "🎉", "🤔", "👀"];

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();

        if (_channels.Count > 0)
        {
            await SelectChannelAsync(_channels[0]);
        }
    }

    private async Task SelectChannelAsync(Channel channel)
    {
        if (_activeChannelId == channel.Id)
            return;

        _activeChannelId = channel.Id;
        _activeChannel = channel;
        _messageSkip = 0;
        _allOlderLoaded = false;
        _messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        _messageSkip = _messages.Count;
        await ChatService.MarkChannelReadAsync(channel.Id);
        BuildThreadSummaries();
    }

    private async Task HandleScrollAsync()
    {
        // Scroll-to-top pagination is triggered via JS interop in production;
        // here we provide fallback logic that can be wired up.
    }

    private async Task LoadOlderMessagesAsync()
    {
        if (_loadingOlder || _allOlderLoaded || _activeChannelId is null)
            return;

        _loadingOlder = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(_activeChannelId.Value, _messageSkip, PageSize);
        if (older.Count < PageSize)
            _allOlderLoaded = true;

        if (older.Count > 0)
        {
            _messages = [..older, ..(_messages ?? [])];
            _messageSkip += older.Count;
            BuildThreadSummaries();
        }

        _loadingOlder = false;
    }

    private async Task SendMessageAsync()
    {
        if (string.IsNullOrWhiteSpace(_newMessageText) || _activeChannelId is null)
            return;

        var sent = await ChatService.SendMessageAsync(_activeChannelId.Value, _newMessageText.Trim(), null);
        _messages ??= [];
        _messages.Add(sent);
        _messageSkip++;
        _newMessageText = string.Empty;
    }

    private async Task HandleMainKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await SendMessageAsync();
        }
    }

    private async Task HandleThreadKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await SendThreadReplyAsync();
        }
    }

    private async Task OpenThreadAsync(Message rootMessage)
    {
        _threadRootMessage = rootMessage;
        _threadReplies = await ChatService.GetThreadAsync(rootMessage.Id);
        _threadOpen = true;
        _emojiPickerMessageId = null;
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadReplies = null;
    }

    private async Task SendThreadReplyAsync()
    {
        if (string.IsNullOrWhiteSpace(_threadReplyText) || _threadRootMessage is null || _activeChannelId is null)
            return;

        var reply = await ChatService.SendMessageAsync(_activeChannelId.Value, _threadReplyText.Trim(), _threadRootMessage.Id);
        _threadReplies ??= [];
        _threadReplies.Add(reply);
        _threadReplyText = string.Empty;

        // Update the summary in the main view
        _threadSummaries[_threadRootMessage.Id] = new ThreadSummary(
            _threadRootMessage.Id,
            _threadReplies.Count,
            reply.SentAt
        );
    }

    private void ToggleEmojiPicker(int messageId)
    {
        _emojiPickerMessageId = _emojiPickerMessageId == messageId ? null : messageId;
    }

    private async Task PickEmojiAsync(int messageId, string emoji)
    {
        await ChatService.AddReactionAsync(messageId, emoji);
        _emojiPickerMessageId = null;

        // Refresh the message reactions in whichever list it belongs to
        if (_messages?.FirstOrDefault(m => m.Id == messageId) is { } mainMsg)
        {
            AddOrUpdateReaction(mainMsg, emoji);
        }
        if (_threadReplies?.FirstOrDefault(m => m.Id == messageId) is { } threadMsg)
        {
            AddOrUpdateReaction(threadMsg, emoji);
        }
    }

    private async Task ReactAsync(int messageId, string emoji)
    {
        await ChatService.AddReactionAsync(messageId, emoji);
        if (_messages?.FirstOrDefault(m => m.Id == messageId) is { } mainMsg)
        {
            AddOrUpdateReaction(mainMsg, emoji);
        }
        if (_threadReplies?.FirstOrDefault(m => m.Id == messageId) is { } threadMsg)
        {
            AddOrUpdateReaction(threadMsg, emoji);
        }
    }

    private static void AddOrUpdateReaction(Message msg, string emoji)
    {
        var existing = msg.Reactions.FirstOrDefault(r => r.Emoji == emoji);
        if (existing is not null)
        {
            if (!existing.Users.Contains("You"))
                existing.Users.Add("You");
        }
        else
        {
            msg.Reactions.Add(new Reaction(emoji, ["You"]));
        }
    }

    private void BuildThreadSummaries()
    {
        if (_messages is null) return;

        _threadSummaries.Clear();
        var replies = _messages.Where(m => m.ReplyToId is not null).ToList();
        foreach (var group in replies.GroupBy(m => m.ReplyToId!.Value))
        {
            _threadSummaries[group.Key] = new ThreadSummary(
                group.Key,
                group.Count(),
                group.Max(m => m.SentAt)
            );
        }
    }

    private ThreadSummary? GetThreadSummary(int messageId)
    {
        _threadSummaries.TryGetValue(messageId, out var summary);
        return summary;
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt.ToUniversalTime();

        return diff.TotalSeconds switch
        {
            < 60 => "just now",
            < 3600 => $"{(int)diff.TotalMinutes} min ago",
            < 86400 => $"{(int)diff.TotalHours}h ago",
            < 604800 => $"{(int)diff.TotalDays}d ago",
            _ => sentAt.ToString("MMM d, yyyy")
        };
    }

    private static string TruncateDescription(string description)
    {
        const int maxLength = 40;
        return description.Length <= maxLength ? description : string.Concat(description.AsSpan(0, maxLength), "…");
    }
}

