+    margin-top: 4px;
+    width: fit-content;
+    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
+}
+
+.emoji-option {
+    background: none;
+    border: none;
+    cursor: pointer;
+    padding: 4px 6px;
+    border-radius: 4px;
+    font-size: 1.15rem;
+    line-height: 1;
+    transition: background 0.1s;
+}
+
+.emoji-option:hover {
+    background: #46484c;
+}
+
+/* ---------- Message Input Area ---------- */
+
+.message-input-area {
+    padding: 12px 20px 16px;
+    border-top: 1px solid #383838;
+    display: flex;
+    gap: 8px;
+    align-items: flex-end;
+    flex-shrink: 0;
+}
+
+.message-input {
+    flex: 1;
+    background: #222529;
+    border: 1px solid #3e4044;
+    border-radius: 8px;
+    color: #d1d2d3;
+    padding: 10px 12px;
+    font-size: 0.9rem;
+    resize: none;
+    outline: none;
+    font-family: inherit;
+    line-height: 1.4;
+}
+
+.message-input:focus {
+    border-color: #1164a3;
+}
+
+.message-input::placeholder {
+    color: #717274;
+}
+
+.send-btn {
+    background: #007a5a;
+    color: #fff;
+    border: none;
+    border-radius: 8px;
+    padding: 10px 18px;
+    font-weight: 700;
+    font-size: 0.875rem;
+    cursor: pointer;
+    white-space: nowrap;
+    transition: background 0.15s;
