+    width: 25%;
+    min-width: 280px;
+    max-width: 420px;
+    background: #222529;
+    border-left: 1px solid #383838;
+    display: flex;
+    flex-direction: column;
+    overflow: hidden;
+}
+
+.thread-header {
+    display: flex;
+    align-items: center;
+    justify-content: space-between;
+    padding: 14px 16px;
+    border-bottom: 1px solid #383838;
+    flex-shrink: 0;
+}
+
+.thread-header h3 {
+    margin: 0;
+    font-size: 1rem;
+    font-weight: 700;
+    color: #fff;
+}
+
+.close-thread-btn {
+    background: none;
+    border: none;
+    color: #9a9b9e;
+    font-size: 1.1rem;
+    cursor: pointer;
+    padding: 4px 8px;
+    border-radius: 4px;
+    transition: background 0.1s;
+}
+
+.close-thread-btn:hover {
+    background: #383838;
+    color: #fff;
+}
+
+.thread-root-quote {
+    padding: 12px 16px;
+    background: #1a1d21;
+    border-bottom: 1px solid #383838;
+    flex-shrink: 0;
+}
+
+.thread-divider {
+    padding: 8px 16px;
+    font-size: 0.75rem;
+    color: #717274;
+    border-bottom: 1px solid #383838;
+    flex-shrink: 0;
+}
+
+.thread-messages {
+    flex: 1;
+    overflow-y: auto;
+    padding: 4px 0;
+}
+
+.thread-reply {
+    padding: 6px 16px;
